74	    if (fd !== undefined) {
75	      try { fs.closeSync(fd); } catch { /* 忽略 */ }
76	    }
77	    try { fs.unlinkSync(tmp); } catch { /* 忽略 */ }
78	    fail(`保存失败：${err.message}（既有存档未改动）`);
79	  }
80	}
