82	// 新建存档：先完整写好临时文件，再用硬链接原子落位。
83	// 目标已存在时 link 失败，绝不覆盖；失败时清理临时文件，不留下可误认的存档。
84	function createSave(file, data) {
85	  if (fs.existsSync(file)) {
86	    fail(`存档已存在：${file}（新建不会覆盖已有存档）`);
87	  }
88	  const tmp = `${file}.tmp-${process.pid}`;
89	  let fd;
90	  try {
91	    fd = fs.openSync(tmp, 'wx');
92	    fs.writeSync(fd, data);
93	    fs.fsyncSync(fd);
94	    fs.closeSync(fd);
95	    fd = undefined;
96	    fs.linkSync(tmp, file);
97	  } catch (err) {
98	    if (fd !== undefined) {
99	      try { fs.closeSync(fd); } catch { /* 忽略 */ }
100	    }
101	    try { fs.unlinkSync(tmp); } catch { /* 忽略 */ }
102	    if (err && err.code === 'EEXIST') {
103	      fail(`存档已存在：${file}（新建不会覆盖已有存档）`);
104	    }
105	    fail(`新建存档失败：${err.message}`);
106	  }
107	  try { fs.unlinkSync(tmp); } catch { /* 忽略 */ }
108	}
109	
110	function loadSave(file) {
111	  let raw;
112	  try {
113	    raw = fs.readFileSync(file, 'utf8');
114	  } catch (err) {
115	    if (err && err.code === 'ENOENT') {
116	      fail(`存档不存在：${file}（请先用 new 命令新建）`);
117	    }
118	    fail(`读取存档失败：${err.message}`);
119	  }
120	  let state;
121	  try {
122	    state = JSON.parse(raw);
123	  } catch {
124	    fail(`存档内容损坏（不是有效 JSON）：${file}，已拒绝继续，存档未被改动`);
125	  }
126	  const problem = validateState(state);
127	  if (problem) {
128	    fail(`存档校验失败：${problem}，已拒绝继续，存档未被改动`);
129	  }
130	  return state;
131	}
