133	// ---------- 校验（含确定性重放，保证状态与记录一致） ----------
134	
135	function isInt(value, min, max) {
136	  return Number.isInteger(value) && value >= min && value <= max;
137	}
138	
139	// 按固定规则重放记录，返回终态；任何一步不一致返回 null。
140	function replay(log) {
141	  let php = PLAYER_MAX_HP;
142	  let ehp = ENEMY_MAX_HP;
143	  let potions = START_POTIONS;
144	  for (let i = 0; i < log.length; i += 1) {
145	    const e = log[i];
146	    if (!e || typeof e !== 'object') return null;
147	    if (e.turn !== i + 1) return null;
148	    let playerDamage = 0;
149	    let healed = 0;
150	    let enemyDamage = 0;
151	    if (e.action === 'attack') {
152	      playerDamage = Math.min(PLAYER_ATTACK, ehp);
153	      ehp -= playerDamage;
154	    } else if (e.action === 'potion') {
155	      if (potions <= 0 || php >= PLAYER_MAX_HP) return null;
156	      potions -= 1;
157	      healed = Math.min(POTION_HEAL, PLAYER_MAX_HP - php);
158	      php += healed;
159	    } else if (e.action !== 'defend') {
160	      return null;
161	    }
162	    let outcome = null;
163	    if (ehp === 0) {
164	      outcome = 'victory';
165	    } else {
166	      enemyDamage = Math.min(e.action === 'defend' ? DEFENDED_DAMAGE : ENEMY_ATTACK, php);
167	      php -= enemyDamage;
168	      if (php === 0) outcome = 'defeat';
169	    }
170	    if (e.playerDamage !== playerDamage || e.healed !== healed ||
171	        e.enemyDamage !== enemyDamage || e.playerHp !== php ||
172	        e.enemyHp !== ehp || e.outcome !== outcome) {
173	      return null;
174	    }
175	    if (outcome !== null && i !== log.length - 1) return null;
176	  }
177	  return { php, ehp, potions };
178	}
179	
180	function validateState(s) {
181	  if (!s || typeof s !== 'object' || Array.isArray(s)) return '存档结构不是对象';
182	  if (s.version !== SAVE_VERSION) return '存档版本不受支持';
183	  if (typeof s.name !== 'string' || s.name.trim() === '') return '角色名为空';
184	  const { player, enemy } = s;
185	  if (!player || typeof player !== 'object' || !enemy || typeof enemy !== 'object') {
186	    return '缺少玩家或敌人数据';
187	  }
188	  if (player.maxHp !== PLAYER_MAX_HP || player.attack !== PLAYER_ATTACK ||
189	      enemy.maxHp !== ENEMY_MAX_HP || enemy.attack !== ENEMY_ATTACK) {
190	    return '固定规则数值被篡改';
191	  }
192	  if (!isInt(player.hp, 0, PLAYER_MAX_HP)) return '玩家生命越界';
193	  if (!isInt(enemy.hp, 0, ENEMY_MAX_HP)) return '敌人生命越界';
194	  if (!isInt(player.potions, 0, Number.MAX_SAFE_INTEGER)) return '药瓶数量越界';
195	  if (!isInt(s.turn, 1, Number.MAX_SAFE_INTEGER)) return '回合数越界';
196	  if (!['ongoing', 'victory', 'defeat'].includes(s.status)) return '结局状态非法';
197	  if (!Array.isArray(s.log)) return '行动记录缺失';
198	  const end = replay(s.log);
199	  if (!end) return '行动记录与规则矛盾';
200	  if (end.php !== player.hp || end.ehp !== enemy.hp || end.potions !== player.potions) {
201	    return '状态与行动记录不一致';
202	  }
203	  if (s.status === 'ongoing') {
204	    if (s.endTurn !== null) return '进行中的存档带有结束回合号';
205	    if (s.turn !== s.log.length + 1) return '回合数与行动记录不连续';
206	    if (player.hp === 0 || enemy.hp === 0) return '结局与生命矛盾';
207	  } else {
208	    if (s.log.length === 0 || s.endTurn !== s.log.length) return '结束回合号与记录矛盾';
209	    if (s.turn !== s.log.length + 1) return '回合数与行动记录不连续';
210	    if (s.status === 'victory' && !(enemy.hp === 0 && player.hp > 0)) return '结局与生命矛盾';
211	    if (s.status === 'defeat' && !(player.hp === 0 && enemy.hp > 0)) return '结局与生命矛盾';
212	  }
213	  return null;
214	}
215	
216	// ---------- 回合结算 ----------
217	
218	function applyAction(state, action) {
219	  const entry = {
220	    turn: state.turn,
221	    action,
222	    playerDamage: 0,
223	    healed: 0,
224	    enemyDamage: 0,
225	    playerHp: state.player.hp,
226	    enemyHp: state.enemy.hp,
227	    outcome: null,
228	  };
229	  if (action === 'attack') {
230	    entry.playerDamage = Math.min(state.player.attack, state.enemy.hp);
231	    state.enemy.hp -= entry.playerDamage;
232	  } else if (action === 'potion') {
233	    if (state.player.potions <= 0) fail('没有治疗药了，喝药被拒绝（本回合未发生）');
234	    if (state.player.hp >= state.player.maxHp) fail('生命已满，喝药被拒绝（本回合未发生）');
235	    state.player.potions -= 1;
236	    entry.healed = Math.min(POTION_HEAL, state.player.maxHp - state.player.hp);
237	    state.player.hp += entry.healed;
238	  }
239	  if (state.enemy.hp === 0) {
240	    state.status = 'victory';
241	    state.endTurn = state.turn;
242	    entry.outcome = 'victory';
243	  } else {
244	    entry.enemyDamage = Math.min(action === 'defend' ? DEFENDED_DAMAGE : state.enemy.attack, state.player.hp);
245	    state.player.hp -= entry.enemyDamage;
246	    if (state.player.hp === 0) {
247	      state.status = 'defeat';
248	      state.endTurn = state.turn;
249	      entry.outcome = 'defeat';
250	    }
251	  }
252	  entry.playerHp = state.player.hp;
253	  entry.enemyHp = state.enemy.hp;
254	  state.log.push(entry);
255	  state.turn += 1;
256	  return entry;
257	}
258	
259	// ---------- 展示 ----------
260	
261	function statusText(s) {
262	  const lines = [
263	    `角色「${s.name}」  生命 ${s.player.hp}/${s.player.maxHp}  治疗药 ${s.player.potions} 瓶`,
264	    `敌人            生命 ${s.enemy.hp}/${s.enemy.maxHp}`,
265	  ];
266	  if (s.status === 'ongoing') {
267	    lines.push(`第 ${s.turn} 回合，战斗进行中`);
268	  } else {
269	    lines.push(s.status === 'victory'
270	      ? `战斗已结束：第 ${s.endTurn} 回合胜利`
271	      : `战斗已结束：第 ${s.endTurn} 回合战败`);
272	  }
273	  return lines.join('\n');
274	}
275	
276	const ACTION_LABEL = { attack: '攻击', defend: '防御', potion: '喝药' };
277	
278	function entryText(e) {
279	  let playerPart;
280	  if (e.action === 'attack') playerPart = `攻击，造成 ${e.playerDamage} 点伤害`;
281	  else if (e.action === 'potion') playerPart = `喝药，恢复 ${e.healed} 点生命`;
282	  else playerPart = '防御';
283	  const enemyPart = e.outcome === 'victory'
284	    ? '敌人倒下，无法反击'
285	    : `敌人反击，造成 ${e.enemyDamage} 点伤害`;
286	  const tail = e.outcome === 'victory' ? '——胜利'
287	    : e.outcome === 'defeat' ? '——战败' : '';
288	  return `第 ${e.turn} 回合：${playerPart}；${enemyPart}。` +
289	    `结算后 角色 ${e.playerHp} 生命 / 敌人 ${e.enemyHp} 生命${tail}`;
290	}
291	
292	// ---------- 命令 ----------
293	
294	function cmdNew(args) {
295	  const [file, ...nameParts] = args;
296	  const name = nameParts.join(' ').trim();
297	  if (!file || name === '') failUsage('用法：node app.js new <存档路径> <角色名>（角色名不能为空）');
298	  const state = initialState(name);
299	  createSave(path.resolve(file), `${JSON.stringify(state, null, 2)}\n`);
300	  console.log(`已为「${name}」新建遭遇：${path.resolve(file)}`);
301	  console.log(statusText(state));
302	}
303	
304	function cmdStatus(args) {
305	  const [file] = args;
306	  if (args.length !== 1) failUsage('用法：node app.js status <存档路径>');
307	  console.log(statusText(loadSave(path.resolve(file))));
308	}
309	
310	function cmdLog(args) {
311	  const [file] = args;
312	  if (args.length !== 1) failUsage('用法：node app.js log <存档路径>');
313	  const state = loadSave(path.resolve(file));
314	  if (state.log.length === 0) {
315	    console.log('（尚无行动记录）');
316	    return;
317	  }
318	  console.log(state.log.map(entryText).join('\n'));
319	}
320	
321	function cmdAct(args) {
322	  const [file, rawAction] = args;
323	  if (args.length !== 2) failUsage('用法：node app.js act <存档路径> <attack|defend|potion>');
324	  const action = ACTIONS.get(rawAction);
325	  if (!action) failUsage(`未知行动：${rawAction}（可选 attack | defend | potion）`);
326	  const resolved = path.resolve(file);
327	  const state = loadSave(resolved);
328	  if (state.status !== 'ongoing') {
329	    fail(`战斗已于第 ${state.endTurn} 回合结束（${state.status === 'victory' ? '胜利' : '战败'}），不能再行动；可查看状态或记录`);
330	  }
331	  const entry = applyAction(state, action); // 无效行动在此抛错，不写盘
332	  writeAtomic(resolved, `${JSON.stringify(state, null, 2)}\n`);
333	  console.log(entryText(entry));
334	  console.log(statusText(state));
335	}
336	
337	const COMMANDS = { new: cmdNew, status: cmdStatus, act: cmdAct, log: cmdLog };
338	
339	function main() {
340	  const args = process.argv.slice(2);
341	  if (args.length === 0 || (args.length === 1 && ['--help', '-h'].includes(args[0]))) {
342	    console.log(HELP);
343	    return;
344	  }
345	  const command = COMMANDS[args[0]];
346	  if (!command) {
347	    console.error(`${NAME}: unknown arguments; use --help`);
348	    process.exitCode = 2;
349	    return;
350	  }
351	  try {
352	    command(args.slice(1));
353	  } catch (err) {
354	    if (err instanceof UsageError) {
355	      console.error(`${NAME}: ${err.message}`);
356	      process.exitCode = 2;
357	    } else if (err instanceof GameError) {
358	      console.error(`${NAME}: ${err.message}`);
359	      process.exitCode = 1;
360	    } else {
361	      throw err;
362	    }
363	  }
364	}
365	
366	main();
